    23	#[derive(Debug, Error)]
    24	pub enum ResolveError {
    25	    #[error("invalid DID {0}")]
    26	    InvalidDid(String),
    27	    #[error("unsupported DID method {0}")]
    28	    UnsupportedMethod(String),
    29	    #[error(transparent)]
    30	    Transport(#[from] TransportError),
    31	    #[error("document for {did} is not a valid DID document: {reason}")]
    32	    InvalidDocument { did: String, reason: String },
    33	    #[error("document fetched for {did} is for {found}")]
    34	    DocumentMismatch { did: String, found: String },
    35	}
