424	#[test]
425	fn an_expiry_before_issuance_is_refused() {
426	    let store = store();
427	    let mut request = membership_request(&Holder::new(1));
428	    request.expires_at = request.issued_at - 1;
429	    assert!(matches!(harbour().issue(&store, &request), Err(IssueError::InvalidValidity)));
430	}
