125	import 'held_credential.dart';
126	import 'holder_key.dart';
127	
128	/// In-memory wallet storage: held credentials by id, and the holder key.
129	class CredentialStore {
130	  final Map<String, HeldCredential> _credentials = {};
131	
132	  void save(HeldCredential credential) =>
133	      _credentials[credential.id] = credential;
134	
135	  HeldCredential? byId(String id) => _credentials[id];
136	
137	  List<HeldCredential> all() => List.unmodifiable(_credentials.values);
138	
139	  HolderKey? holderKey;
140	}
141	/// One salted claim the holder can reveal: its digest sits in the credential.
142	class Disclosure {
143	  const Disclosure({
144	    required this.salt,
145	    required this.name,
146	    required this.value,
147	  });
148	
149	  factory Disclosure.fromJson(Object? json) {
150	    if (json is Map<String, dynamic>) {
151	      return Disclosure(
152	        salt: json['salt'] as String,
153	        name: json['name'] as String,
154	        value: json['value'],
155	      );
156	    }
157	    if (json is List && json.length == 3) {
158	      return Disclosure(
159	        salt: json[0] as String,
160	        name: json[1] as String,
161	        value: json[2],
162	      );
163	    }
164	    throw FormatException('Unrecognised disclosure: $json');
165	  }
166	
167	  final String salt;
168	  final String name;
169	  final Object? value;
170	
171	  Map<String, dynamic> toJson() => {'salt': salt, 'name': name, 'value': value};
172	}
173	
174	/// A credential in the wallet: the issuer-signed document plus the
175	/// disclosures that go with it.
176	class HeldCredential {
177	  HeldCredential({required this.vc, required this.disclosures});
178	
179	  /// Parses the issuer's response: `{"credential": {...}, "disclosures": [...]}`.
180	  factory HeldCredential.fromIssuance(Map<String, dynamic> json) {
181	    final vc = json['credential'];
182	    if (vc is! Map<String, dynamic>) {
183	      throw const FormatException('Issuance response has no credential');
184	    }
185	    final disclosures = (json['disclosures'] as List? ?? const [])
186	        .map(Disclosure.fromJson)
187	        .toList();
188	    return HeldCredential(vc: vc, disclosures: disclosures);
189	  }
190	
191	  final Map<String, dynamic> vc;
192	  final List<Disclosure> disclosures;
193	
194	  String get id => vc['id'] as String;
195	
196	  String get issuer {
197	    final issuer = vc['issuer'];
198	    return issuer is Map ? issuer['id'] as String : issuer as String;
199	  }
200	
201	  String? get holderDid =>
202	      (vc['credentialSubject'] as Map<String, dynamic>?)?['id'] as String?;
203	
204	  /// The most specific type, e.g. `MembershipCredential`.
205	  String get type {
206	    final types = vc['type'];
207	    return types is List ? types.last as String : types as String;
208	  }
209	
210	  Map<String, dynamic> toJson() => {
211	    'credential': vc,
212	    'disclosures': disclosures.map((d) => d.toJson()).toList(),
213	  };
214	}
215	import 'dart:typed_data';
216	
217	import 'package:ssi/ssi.dart';
218	
219	/// The holder's signing key and the did:key derived from it.
220	class HolderKey {
221	  HolderKey._(this.keyPair) : did = DidKey.getDid(keyPair.publicKey);
222	
223	  /// A fresh random Ed25519 key.
224	  factory HolderKey.generate() {
225	    final (keyPair, _) = Ed25519KeyPair.generate();
226	    return HolderKey._(keyPair);
227	  }
228	
229	  /// A key restored from its 32-byte seed.
230	  factory HolderKey.fromSeed(Uint8List seed) =>
231	      HolderKey._(Ed25519KeyPair.fromSeed(seed));
232	
233	  final Ed25519KeyPair keyPair;
234	  final String did;
235	
236	  /// The verification method id inside the did:key document.
237	  String get keyId => '$did#${did.substring('did:key:'.length)}';
238	
239	  Future<Uint8List> sign(List<int> data) =>
240	      keyPair.sign(Uint8List.fromList(data));
241	
242	  Future<bool> verify(List<int> data, List<int> signature) =>
243	      keyPair.verify(Uint8List.fromList(data), Uint8List.fromList(signature));
244	}
245	import 'held_credential.dart';
246	
247	/// Talks to the issuer service.
248	abstract interface class IssuerClient {
249	  /// Asks the issuer for a [credentialType] credential about [holderDid].
250	  Future<HeldCredential> issue({
251	    required String holderDid,
252	    required String credentialType,
253	  });
254	}
255	import 'package:dcql/dcql.dart';
256	
257	/// A verifier's request for a presentation, in the OpenID4VP shape:
258	/// who is asking (`client_id`), a `nonce`, and a DCQL query.
259	class PresentationRequest {
260	  const PresentationRequest({
261	    required this.clientId,
262	    required this.nonce,
263	    required this.dcqlQuery,
264	    this.responseUri,
265	  });
266	
267	  factory PresentationRequest.fromJson(Map<String, dynamic> json) {
268	    final clientId = json['client_id'];
269	    final nonce = json['nonce'];
270	    final query = json['dcql_query'];
271	    if (clientId is! String || clientId.isEmpty) {
272	      throw const FormatException('Presentation request has no client_id');
273	    }
274	    if (nonce is! String || nonce.isEmpty) {
275	      throw const FormatException('Presentation request has no nonce');
276	    }
277	    if (query is! Map<String, dynamic>) {
278	      throw const FormatException('Presentation request has no dcql_query');
279	    }
280	    final responseUri = json['response_uri'];
281	    return PresentationRequest(
282	      clientId: clientId,
283	      nonce: nonce,
284	      dcqlQuery: DcqlCredentialQuery.fromJson(query),
285	      responseUri: responseUri is String ? Uri.parse(responseUri) : null,
286	    );
287	  }
288	
289	  final String clientId;
290	  final String nonce;
291	  final DcqlCredentialQuery dcqlQuery;
292	  final Uri? responseUri;
293	
294	  /// The domain a presentation for this request is addressed to.
295	  String get domain => clientId;
296	
297	  Map<String, dynamic> toJson() => {
298	    'client_id': clientId,
299	    'nonce': nonce,
300	    'dcql_query': dcqlQuery.toJson(),
301	    if (responseUri != null) 'response_uri': responseUri.toString(),
302	  };
303	}
304	import 'credential_store.dart';
305	import 'held_credential.dart';
306	import 'holder_key.dart';
307	import 'issuer_client.dart';
308	import 'presentation_request.dart';
309	
310	class WalletException implements Exception {
311	  const WalletException(this.message);
312	  final String message;
313	  @override
314	  String toString() => 'WalletException: $message';
315	}
316	
317	/// The wallet's operations: holder key, credential requests, presentations.
318	class WalletService {
319	  WalletService({
320	    required this._issuer,
321	    CredentialStore? store,
322	    HolderKey Function()? newKey,
323	  }) : _store = store ?? CredentialStore(),
324	       _newKey = newKey ?? HolderKey.generate;
325	
326	  final IssuerClient _issuer;
327	  final CredentialStore _store;
328	  final HolderKey Function() _newKey;
329	
330	  /// The holder key, created on first use.
331	  HolderKey holderKey() => _store.holderKey ??= _newKey();
332	
333	  /// Requests a [credentialType] credential for this holder and keeps it.
334	  Future<HeldCredential> requestCredential(String credentialType) async {
335	    final did = holderKey().did;
336	    final credential = await _issuer.issue(
337	      holderDid: did,
338	      credentialType: credentialType,
339	    );
340	    if (credential.holderDid != did) {
341	      throw WalletException(
342	        'Credential ${credential.id} was issued to ${credential.holderDid}, not $did',
343	      );
344	    }
345	    _store.save(credential);
346	    return credential;
347	  }
348	
349	  List<HeldCredential> heldCredentials() => _store.all();
350	
351	  HeldCredential? credential(String id) => _store.byId(id);
352	
353	  /// Builds a presentation of the held credential [credentialId] in answer
354	  /// to [request], ready to send to the requester.
355	  Future<Map<String, dynamic>> createPresentation(
356	    String credentialId,
357	    PresentationRequest request,
358	  ) async {
359	    throw UnimplementedError('createPresentation');
360	  }
361	}

