    /// Subscribes `count` subscribers whose URLs are all on one host,
    /// answered as `endpoint`; returns their ids.
    fn subscribers_on_one_host(&self, host: &str, count: usize, endpoint: Endpoint) -> Vec<String> {
        self.transport.route_host(&format!("{host}.rp.example"), endpoint);
        (0..count)
            .map(|i| {
                let id = format!("{host}-{i:05}");
                let url = format!("https://{host}.rp.example/hooks/{i}");
                self.settings.put(Setting::new(LEAGUE, &format!("webhook/{id}"), WEBHOOK_KIND, json!({ "url": url })));
                id
            })
            .collect()
    }

    fn missed<'a>(&self, urls: &'a [String]) -> Vec<&'a str> {
        urls.iter().filter(|url| self.transport.received(url).len() != 1).map(String::as_str).collect()
    }

    /// The failure reasons recorded for `subscription`.
    fn failures(&self, subscription: &str) -> Vec<String> {
        self.sink
            .events()
            .into_iter()
            .filter(|e| e.subscription == subscription)
            .filter_map(|e| match e.outcome {
                Outcome::Failed { reason } => Some(reason),
                Outcome::Delivered { .. } => None,
            })
            .collect()
    }
}

